// Runs every hour. True WhatsApp-style behavior: any photo/file gets
// deleted from OUR storage exactly 48 hours after it was sent — the
// customer already has their own permanent copy on their phone via
// WhatsApp, same as real WhatsApp servers do. The chat bubble/history
// stays forever; only the actual file bytes on our side get cleaned up.

const anonKey = '[REDACTED_SUPABASE_ANON_KEY]';
const botToken = '[REDACTED_TELEGRAM_BOT_TOKEN]';

const RETENTION_HOURS = 48; // change this one number to adjust the window

function httpJson(method, path, bodyObj) {
  return new Promise((resolve) => {
    const https = require('https');
    const bodyStr = JSON.stringify(bodyObj);
    const req = https.request({
      hostname: 'qfmmoobwzuhiimmjixes.supabase.co',
      path,
      method,
      headers: {
        'Authorization': 'Bearer ' + anonKey,
        'apikey': anonKey,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(bodyStr)
      }
    }, (res) => {
      let raw = '';
      res.on('data', (c) => { raw += c; });
      res.on('end', () => {
        try { resolve(JSON.parse(raw)); } catch (e) { resolve(null); }
      });
    });
    req.on('error', () => resolve(null));
    req.write(bodyStr);
    req.end();
  });
}

async function listAllObjects() {
  const topLevel = await httpJson('POST', '/storage/v1/object/list/chat-media', { prefix: '', limit: 1000 });
  const folders = (topLevel || []).filter(o => !o.id);
  let all = [];
  for (const folder of folders) {
    const items = await httpJson('POST', '/storage/v1/object/list/chat-media', { prefix: folder.name + '/', limit: 1000 });
    (items || []).forEach(it => {
      if (it.id) {
        all.push({
          path: folder.name + '/' + it.name,
          sellerId: folder.name,
          createdAt: it.created_at || it.updated_at
        });
      }
    });
  }
  return all;
}

async function deleteObjects(paths) {
  if (paths.length === 0) return;
  await httpJson('DELETE', '/storage/v1/object/chat-media', { prefixes: paths });
}

const objects = await listAllObjects();
const now = Date.now();
const hourMs = 60 * 60 * 1000;

const expired = objects.filter(o => (now - new Date(o.createdAt).getTime()) >= RETENTION_HOURS * hourMs);

if (expired.length > 0) {
  await deleteObjects(expired.map(o => o.path));
}

return [{ json: { checked: objects.length, deleted: expired.length } }];
